const test = require('node:test');
const assert = require('node:assert/strict');
const { createNoticeBus } = require('../notices.cjs');
test('self-removal cannot skip the next subscriber', () => {
  const bus = createNoticeBus(), log = [];
  let stop;
  stop = bus.on(value => { log.push('A:' + value); stop(); });
  bus.on(value => log.push('B:' + value));
  bus.emit('tick1'); bus.emit('tick2');
  assert.deepEqual(log, ['A:tick1','B:tick1','B:tick2']);
});
test('removal and addition affect the following emit', () => {
  const bus = createNoticeBus(), log = [];
  let changed = false, stopB;
  bus.on(value => {
    log.push('A:' + value);
    if (!changed) {
      changed = true;
      stopB();
      bus.on(item => log.push('C:' + item));
    }
  });
  stopB = bus.on(value => log.push('B:' + value));
  bus.emit(1); bus.emit(2);
  assert.deepEqual(log, ['A:1','B:1','A:2','C:2']);
});
test('duplicate callback registrations are independent', () => {
  const bus = createNoticeBus();
  const seen = [], fn = value => seen.push(value);
  const stop = bus.on(fn);
  bus.on(fn);
  bus.emit('x'); stop(); stop(); bus.emit('y');
  assert.deepEqual(seen, ['x','x','y']);
});

