function createNoticeBus() {
  const listeners = [];
  return {
    on(fn) {
      const entry = { fn };
      listeners.push(entry);
      return () => {
        const index = listeners.indexOf(entry);
        if (index !== -1) listeners.splice(index, 1);
      };
    },
    emit(value) {
      for (const entry of [...listeners]) entry.fn(value);
    }
  };
}
module.exports = { createNoticeBus };
